@Component("screeningResult-handler")
@ProcessingGroup("screeningResult-processing-group")
public class ScreeningResultEventHandler {
	
	// core constructor
	ScreeningResultEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateScreeningResultEvent
     */
    @EventHandler
    public void handle( CreateScreeningResultEvent event) {
        entityManager.persist(new ScreeningResult(event.getScreeningResultId(), event.getScreeningDate(), event.getProvider(), event.getKycProfile(), event.getOutcome()));
    }

    /*
     * @param	event UpdateScreeningResultEvent
     */
    @EventHandler
    public ScreeningResult handle( UpdateScreeningResultEvent event) {
    	entityManager.merge(new ScreeningResult(event.getScreeningResultId(), event.getScreeningDate(), event.getProvider(), event.getKycProfile(), event.getOutcome()));
    }
    
    /*
     * @param	event DeleteScreeningResultEvent
     */
    @EventHandler
    public void on( DeleteScreeningResultEvent event) {
    	ScreeningResult entity = new ScreeningResult();
   
    	// ------------------------------------------
    	// apply the ScreeningResultId
    	// ------------------------------------------
    	entity.setScreeningResultId( event.getScreeningResultId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ScreeningResultRepository screeningResultEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ScreeningResultEventHandler.class.getName());

}
